import multiprocessing as m,time,json,os
def burn():
 while True:pass
workers=[m.get_context('fork').Process(target=burn,daemon=True) for _ in range(2)]
for worker in workers:worker.start()
print(json.dumps({'workers':[w.pid for w in workers],'affinity':sorted(os.sched_getaffinity(0))}),flush=True)
end=time.monotonic()+600
while time.monotonic()<end:
 if not all(w.is_alive() for w in workers):raise RuntimeError('CPU worker exited early')
 time.sleep(.5)

